using System;

class Program
{
    static string Kind(string cmd)
    {
        switch (cmd)                   // string switch: ordinal comparison
        {
            case "start":
            case "run":                // empty sections may stack
                return "launch";
            case "stop":
                return "halt";
            default:
                return "unknown";
        }
    }

    static void Main()
    {
        int day = 2;
        switch (day)
        {
            case 1:
            case 2:
                Console.WriteLine("early week");
                goto case 5;           // explicit jump replaces fall-through
            case 5:
                Console.WriteLine("reached via goto case");
                break;                 // every non-empty section must end like this
        }
        foreach (string c in new[] { "start", "run", "stop", "Stop" })
            Console.WriteLine(c + " -> " + Kind(c));   // "Stop" does not match "stop"
        object o = 42;
        if (o is int) Console.WriteLine("type test: int " + (int)o);  // pre-pattern style
    }
}

using System;

class Program
{
    static void Mutate(int[] a) { a[0] = 99; }              // changes shared object
    static void Reassign(int[] a) { a = new int[] { 1 }; }  // only changes the local copy
    static void ReassignRef(ref int[] a) { a = new int[] { 1 }; } // changes caller's variable
    static void IncValue(int x) { x++; }
    static void IncRef(ref int x) { x++; }

    static void Main()
    {
        int n = 5;
        IncValue(n);
        Console.WriteLine("after IncValue: " + n);   // 5
        IncRef(ref n);
        Console.WriteLine("after IncRef: " + n);     // 6

        int[] arr = { 10, 20, 30 };
        Mutate(arr);
        Console.WriteLine("after Mutate: " + string.Join(",", arr));       // 99,20,30
        Reassign(arr);
        Console.WriteLine("after Reassign: " + string.Join(",", arr));     // unchanged
        ReassignRef(ref arr);
        Console.WriteLine("after ReassignRef: " + string.Join(",", arr));  // 1
    }
}

using System;

class Program
{
    // Try pattern: cheap, no exception when failure is common
    static bool TryHalf(int x, out int half)
    {
        half = 0;
        if (x % 2 != 0) return false;
        half = x / 2;
        return true;
    }

    // Exception: failure is exceptional
    static int HalfOrThrow(int x)
    {
        if (x % 2 != 0) throw new ArgumentException("odd: " + x);
        return x / 2;
    }

    static Tuple<int, int> MinMax(int[] a)   // several meaningful results
    {
        int lo = a[0], hi = a[0];
        foreach (int v in a) { if (v < lo) lo = v; if (v > hi) hi = v; }
        return Tuple.Create(lo, hi);
    }

    static void Main()
    {
        foreach (string s in new[] { "42", "x7", "" })
        {
            int v;
            bool ok = int.TryParse(s, out v);   // BCL Try pattern
            Console.WriteLine("'" + s + "' -> " + ok + " " + v);
        }
        int h;
        Console.WriteLine(TryHalf(10, out h) + " " + h);
        Console.WriteLine(TryHalf(7, out h) + " " + h);
        try { HalfOrThrow(7); } catch (ArgumentException e) { Console.WriteLine("caught " + e.Message); }
        Tuple<int, int> mm = MinMax(new[] { 4, 9, -2, 7 });
        Console.WriteLine("min " + mm.Item1 + " max " + mm.Item2);
    }
}

using System;

struct Counter
{
    public int Value;
    public void Increment() { Value++; }   // mutates the struct
}

class Holder
{
    public readonly Counter C = new Counter();   // readonly field of a mutable struct
}

class Program
{
    static void ByValue(Counter c) { c.Increment(); }        // works on a copy
    static void ByRef(ref Counter c) { c.Increment(); }      // no copy, but callee may mutate

    static void Main()
    {
        Counter c = new Counter();
        ByValue(c);
        Console.WriteLine("after ByValue: " + c.Value);   // 0 (copied)
        ByRef(ref c);
        Console.WriteLine("after ByRef:   " + c.Value);   // 1 (no copy)

        // Calling a method on a readonly field: the compiler cannot prove the method
        // leaves the struct alone, so it calls it on a hidden copy (defensive copy).
        Holder h = new Holder();
        h.C.Increment();
        Console.WriteLine("readonly field after Increment: " + h.C.Value);  // 0
        // 'in' (C# 7.2+) gives no-copy read-only passing; marking the struct readonly avoids the copy
    }
}

