class Base
{
    public void F(int x) { Console.WriteLine("Base.F(int " + x + ")"); }
}

class Derived : Base
{
    public void F(double x) { Console.WriteLine("Derived.F(double " + x + ")"); }
}

class Program
{
    static void P(string s) { Console.WriteLine("P(string)"); }
    static void P(object o) { Console.WriteLine("P(object)"); }
    static void Q(long x) { Console.WriteLine("Q(long)"); }
    static void Q(double x) { Console.WriteLine("Q(double)"); }
    static void G(int x) { Console.WriteLine("G(int)"); }
    static void G<T>(T x) { Console.WriteLine("G<T>"); }

    static void Main()
    {
        P(null);            // string is more specific than object
        Q(5);               // int -> long is better than int -> double
        G(5);               // non-generic beats generic
        G("s");             // only generic applies
        Derived d = new Derived();
        d.F(5);             // Derived.F(double) wins: compiler stops at the first class with an applicable method
        ((Base)d).F(5);     // through a Base reference: Base.F(int)
    }
}

using System;

interface IGreeter
{
    string Greet(string name = "interface-default");
}

class Greeter : IGreeter
{
    // The class declares a different default value
    public string Greet(string name = "class-default")
    {
        return "Hello, " + name;
    }
}

class Program
{
    static void Main()
    {
        Greeter g = new Greeter();
        IGreeter i = g;                 // same object, different static type
        Console.WriteLine(g.Greet());   // compiler inserts "class-default" at the call site
        Console.WriteLine(i.Greet());   // compiler inserts "interface-default"
        // The default is baked into the caller's compiled code, so changing it in a
        // library does nothing for callers until they are recompiled.
        // Safer API evolution: add an overload instead of a new optional parameter.
        Console.WriteLine(g.Greet("Ada"));
    }
}

using System;

class Program
{
    static void Main()
    {
        int[,] rect = new int[3, 4];            // one object, 12 contiguous ints
        int[][] jag = new int[3][];             // array of 3 references
        for (int r = 0; r < 3; r++)
        {
            jag[r] = new int[r + 1];            // rows may have different lengths
            for (int c = 0; c < 4; c++) rect[r, c] = r * 4 + c;
            for (int c = 0; c < jag[r].Length; c++) jag[r][c] = r * 10 + c;
        }

        long sumRect = 0;
        for (int r = 0; r < rect.GetLength(0); r++)
            for (int c = 0; c < rect.GetLength(1); c++)
                sumRect += rect[r, c];          // offset computed from r and c
        Console.WriteLine("rectangular sum = " + sumRect + ", total elements " + rect.Length);

        long sumJag = 0;
        for (int r = 0; r < jag.Length; r++)
        {
            int[] row = jag[r];                 // hoist the row: single-dimension access is fast
            for (int c = 0; c < row.Length; c++) sumJag += row[c];
            Console.WriteLine("jagged row " + r + " length " + row.Length + ": " + string.Join(",", row));
        }
        Console.WriteLine("jagged sum = " + sumJag + ", objects allocated = " + (1 + jag.Length));
        int[] flat = new int[3 * 4];            // fastest option: flat array
        flat[1 * 4 + 2] = 7;                    // row 1, col 2
        Console.WriteLine("flat[1*4+2] = " + flat[6]);
    }
}

