class Program
{
    static void Main()
    {
        string s = "hello";
        s.ToUpper();                      // bug: result thrown away, s is unchanged
        Console.WriteLine("after ToUpper without assignment: " + s);
        string t = s.ToUpper();           // a NEW string
        Console.WriteLine("assigned: " + t + ", original: " + s);

        string a = "net";
        string b = "net";
        Console.WriteLine("same literal, same object: " + object.ReferenceEquals(a, b));  // interned
        string c = new string(new char[] { 'n', 'e', 't' });
        Console.WriteLine("built at runtime, same object: " + object.ReferenceEquals(a, c));
        Console.WriteLine("after Intern, same object: " + object.ReferenceEquals(a, string.Intern(c)));

        // Concatenating in a loop makes n new strings: O(n^2) characters copied
        string slow = "";
        for (int i = 0; i < 5; i++) slow += i;
        StringBuilder sb = new StringBuilder();       // amortised O(1) appends
        for (int i = 0; i < 5; i++) sb.Append(i);
        Console.WriteLine(slow + " " + sb.ToString() + " equal=" + (slow == sb.ToString()));
    }
}

