        string[] words = { "banana", "Apple", "cherry", "apple" };
        string[] ord = (string[])words.Clone();
        Array.Sort(ord, StringComparer.Ordinal);
        Console.WriteLine("Ordinal order:           " + string.Join(", ", ord));
        string[] ic = (string[])words.Clone();
        Array.Sort(ic, StringComparer.OrdinalIgnoreCase);
        Console.WriteLine("OrdinalIgnoreCase order: " + string.Join(", ", ic));

        // Case-insensitive dictionary: pass the comparer once
        Dictionary<string, int> d = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        d["Content-Type"] = 1;
        Console.WriteLine("lookup 'content-type': " + d.ContainsKey("content-type"));
        Console.WriteLine("CompareOrdinal('Z','a') < 0: " + (string.CompareOrdinal("Z", "a") < 0));
    }
}

using System;
using System.Text;

class Program
{
    static void Main()
    {
        int n = 2000;

        // Each += allocates a new string and copies all previous characters: O(n^2)
        string s = "";
        for (int i = 0; i < n; i++) s += "ab";

        // StringBuilder appends into spare capacity, growing by chunks: amortised O(1) each
        StringBuilder sb = new StringBuilder(n * 2);   // pre-size when the length is known
        for (int i = 0; i < n; i++) sb.Append("ab");
        string t = sb.ToString();                       // one final copy

        Console.WriteLine("lengths: " + s.Length + " and " + t.Length);
        Console.WriteLine("same content: " + (s == t));

        // Not worth it for a few pieces: one Concat call, one allocation
        string name = "Ada";
        int age = 36;
        string small = "Name=" + name + ", Age=" + age;
        Console.WriteLine(small);
        Console.WriteLine(string.Join("|", new[] { "a", "b", "c" }));   // join collections
        Console.WriteLine("copied chars by +=: " + (long)n * (n + 1) + ", by builder: " + (2 * n));
    }
}

