import java.util.*;

public class Main {
    static class Node {
        int val; Node left, right;
        Node(int v) { val = v; }
    }

    static Node insert(Node root, int v) {
        if (root == null) return new Node(v);
        if (v < root.val) root.left = insert(root.left, v);
        else root.right = insert(root.right, v);
        return root;
    }

    // Iterative in-order: O(n) time, O(h) space on the heap, no stack overflow
    static List<Integer> inorder(Node root) {
        List<Integer> out = new ArrayList<>();
        Deque<Node> stack = new ArrayDeque<>();
        Node cur = root;
        while (cur != null || !stack.isEmpty()) {
            while (cur != null) { stack.push(cur); cur = cur.left; }  // go left
            cur = stack.pop();
            out.add(cur.val);                                          // visit
            cur = cur.right;                                           // then right
        }
        return out;
    }

    public static void main(String[] args) {
        int[] values = {50, 30, 70, 20, 40, 60, 80};
        Node root = null;
        for (int v : values) root = insert(root, v);
        System.out.println("inserted: " + Arrays.toString(values));
        System.out.println("in-order: " + inorder(root));
    }
}

