#include <bits/stdc++.h>
using namespace std;

struct Node {
    int val;
    Node *left = nullptr, *right = nullptr;
    Node(int v) : val(v) {}
};

Node* insert(Node* root, int v) {
    if (!root) return new Node(v);
    if (v < root->val) root->left = insert(root->left, v);
    else root->right = insert(root->right, v);
    return root;
}

// Iterative in-order: O(n) time, O(h) space on the heap, no stack overflow
vector<int> inorder(Node* root) {
    vector<int> out;
    stack<Node*> st;
    Node* cur = root;
    while (cur || !st.empty()) {
        while (cur) { st.push(cur); cur = cur->left; }  // go left
        cur = st.top(); st.pop();
        out.push_back(cur->val);                         // visit
        cur = cur->right;                                // then right
    }
    return out;
}

int main() {
    vector<int> values = {50, 30, 70, 20, 40, 60, 80};
    Node* root = nullptr;
    for (int v : values) root = insert(root, v);
    auto print = [](const char* label, const vector<int>& a) {
        cout << label << "[";
        for (size_t i = 0; i < a.size(); i++) cout << (i ? ", " : "") << a[i];
        cout << "]\n";
    };
    print("inserted: ", values);
    print("in-order: ", inorder(root));
}

