using System;
using System.Collections.Generic;

class Node
{
    public int Val;
    public Node Left, Right;
    public Node(int v) { Val = v; }
}

class Program
{
    static Node Insert(Node root, int v)
    {
        if (root == null) return new Node(v);
        if (v < root.Val) root.Left = Insert(root.Left, v);
        else root.Right = Insert(root.Right, v);
        return root;
    }

    // Iterative in-order: O(n) time, O(h) space on the heap, no stack overflow
    static List<int> InOrder(Node root)
    {
        List<int> output = new List<int>();
        Stack<Node> stack = new Stack<Node>();
        Node cur = root;
        while (cur != null || stack.Count > 0)
        {
            while (cur != null) { stack.Push(cur); cur = cur.Left; }  // go left
            cur = stack.Pop();
            output.Add(cur.Val);                                       // visit
            cur = cur.Right;                                           // then right
        }
        return output;
    }

    static void Main()
    {
        int[] values = { 50, 30, 70, 20, 40, 60, 80 };
        Node root = null;
        foreach (int v in values) root = Insert(root, v);
        Console.WriteLine("inserted: [" + string.Join(", ", values) + "]");
        Console.WriteLine("in-order: [" + string.Join(", ", InOrder(root)) + "]");
    }
}

using System;

class Program
{
    static void Main()
    {
        int[] a = { 10, 20, 30, 40, 50 };

        // Copy: allocates a new array, O(n) per slice (what a[1..] does for arrays)
        int[] copy = new int[a.Length - 1];
        Array.Copy(a, 1, copy, 0, copy.Length);

        // View: no copy, shares the same memory (like AsSpan(1..) / ArraySegment)
        ArraySegment<int> view = new ArraySegment<int>(a, 1, a.Length - 1);

        a[1] = 999;   // change the original
        Console.WriteLine("original: " + string.Join(",", a));
        Console.WriteLine("copy:     " + string.Join(",", copy) + "  (unaffected)");
        Console.WriteLine("view[0]:  " + view.Array[view.Offset + 0] + "  (sees the change)");

        // Index from the end by hand: what a[^1] is rewritten to
        Console.WriteLine("last element a[a.Length - 1] = " + a[a.Length - 1]);
        // a[^0] would be a[a.Length], one past the end: always out of range
        try { Console.WriteLine(a[a.Length - 0]); }
        catch (IndexOutOfRangeException) { Console.WriteLine("a[^0] equivalent throws IndexOutOfRangeException"); }
    }
}

using System;

class Program
{
    static int[] lastSeen;

    static int Sum(params int[] values)
    {
        lastSeen = values;                       // remember which array we received
        int total = 0;
        foreach (int v in values) total += v;
        return total;
    }

    static int Sum2(int a, int b) { return a + b; }   // fixed-arity overload: no array

    static void Main()
    {
        Console.WriteLine("Sum(1,2,3) = " + Sum(1, 2, 3));
        int[] first = lastSeen;
        Console.WriteLine("Sum(1,2,3) = " + Sum(1, 2, 3));
        Console.WriteLine("a new array each call: " + !object.ReferenceEquals(first, lastSeen));

        int[] mine = { 4, 5, 6 };
        Console.WriteLine("Sum(mine) = " + Sum(mine));                          // normal form
        Console.WriteLine("existing array reused: " + object.ReferenceEquals(mine, lastSeen));

        Sum();                                                                  // empty array
        Console.WriteLine("Sum() gets an empty array of length " + lastSeen.Length);
        try { Sum(null); Console.WriteLine("Sum(null) is not an error here"); }
        catch (NullReferenceException) { Console.WriteLine("Sum(null) passes a null array: NullReferenceException"); }
        Console.WriteLine("Sum2(4, 5) = " + Sum2(4, 5));
    }
}

using System;
using System.Text;

class Logger
{
    public int Level = 2;               // 1 = debug, 2 = info, 3 = error
    public int StringsBuilt = 0;
    private readonly StringBuilder reuse = new StringBuilder(256);  // reused buffer

    public bool IsEnabled(int level) { return level >= Level; }

    // Naive: always builds the message, even when the level is off
    public string Naive(int level, string msg, int id)
    {
        StringsBuilt++;
        return "[" + level + "] " + msg + " id=" + id;
    }

    // Better: check the level first and reuse one builder
    public string Better(int level, string msg, int id)
    {
        if (!IsEnabled(level)) return null;       // no work for disabled levels
        reuse.Clear();
        reuse.Append('[').Append(level).Append("] ").Append(msg).Append(" id=").Append(id);
        StringsBuilt++;                           // one ToString copy at the end
        return reuse.ToString();
    }
}

class Program
{
    static void Main()
    {
        Logger a = new Logger(), b = new Logger();
        for (int i = 0; i < 1000; i++)
        {
            a.Naive(1, "debug detail", i);        // level 1 is disabled but still formatted
            b.Better(1, "debug detail", i);
        }
        Console.WriteLine("naive strings built:  " + a.StringsBuilt);
        Console.WriteLine("better strings built: " + b.StringsBuilt);
        Console.WriteLine(b.Better(3, "disk full", 7));
    }
}
